void HandleBufferResourceCreation(PP_Instance instance, uint32_t size, HostResource* result_resource, ppapi::proxy::SerializedHandle* result_shm_handle) {
    // Check for necessary permissions and resource creation validity
    if (!IsValidInstance(instance) || size == 0 || !result_resource || !result_shm_handle) {
        return;
    }

    // Create the buffer resource
    HostResource buffer_resource = CreateBufferResource(instance, size);
    if (!buffer_resource.IsValid()) {
        return;
    }

    // Retrieve shared memory handle
    ppapi::proxy::SerializedHandle shm_handle;
    if (!GetSharedMemoryHandle(buffer_resource, &shm_handle)) {
        return;
    }

    // Set result values for the caller
    *result_resource = buffer_resource;
    *result_shm_handle = shm_handle;

#if defined(OS_POSIX)
    // Platform-specific handling for file descriptors (POSIX)
    int fd = shm_handle.fd();
    if (fd < 0) {
        return;
    }
    fcntl(fd, F_SETFD, FD_CLOEXEC);
#endif

#if defined(OS_WIN)
    // Platform-specific handling for shared memory on Windows
    HANDLE handle = shm_handle.handle();
    if (!handle) {
        return;
    }
#endif
}

void HandleBufferCreation(PP_Instance instance, uint32_t size, HostResource* result_resource, ppapi::proxy::SerializedHandle* result_shm_handle) {
    // Check for necessary permissions and resource creation validity
    if (!CheckPermissions(instance) || !ValidateResourceCreation(size)) {
        return;
    }

    // Create the buffer and retrieve shared memory handle
    void* buffer = CreateBufferResource(instance, size);
    if (!buffer) {
        return;
    }

    // Retrieve the shared memory handle (platform-specific)
    ppapi::proxy::SerializedHandle shm_handle = GetSharedMemoryHandle(buffer, size);
    if (!shm_handle.IsValid()) {
        DestroyBufferResource(buffer);
        return;
    }

    // Assign the result resource and shared memory handle
    *result_resource = GetResourceFromBuffer(buffer);
    *result_shm_handle = shm_handle;
}

void CreateBufferResource(PP_Instance instance, uint32_t size, HostResource* result_resource, ppapi::proxy::SerializedHandle* result_shm_handle) {
  // Check for necessary permissions and validity of resource creation
  if (!IsValidInstance(instance) || size == 0 || !result_resource || !result_shm_handle) {
    return;
  }

  // Platform-specific handling
  int fd = -1;
  #if defined(OS_POSIX)
    fd = CreateSharedMemoryFd(size);
  #elif defined(OS_WIN)
    fd = CreateSharedMemoryWinHandle(size);
  #endif

  if (fd < 0) {
    return;
  }

  // Create the buffer resource
  HostResource buffer_resource = CreateResourceFromFd(instance, fd, size);
  if (!buffer_resource.IsValid()) {
    CloseFd(fd);
    return;
  }

  *result_resource = buffer_resource;
  ppapi::proxy::SerializedHandle shm_handle;
  shm_handle.SetFd(fd);

  *result_shm_handle = shm_handle;
}

